-- Dungeon Master's Guide v3.5 Chapter 7: standard magic rings, pp. 230-233.
-- Mechanical text is summarized; the supplied DMG and appended errata remain authoritative.
-- Rings use slot='other' to match the existing catalog convention; the equipment service may assign either ring slot at runtime.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg-3.5','dungeon-masters-guide-3-5','Dungeon Master''s Guide','DMG','Wizards of the Coast','dnd','3.5',
        'Core Rulebook II; source for D&D v3.5 magic items, treasure, special materials, and Dungeon Master rules.',NULL,1,0,NULL);

WITH desired(
  id,page,slug,name,price_copper,caster_level,aura_strength,activation,activation_text,
  maximum_charges,recharge_text,description,rules_text,crafting_text
) AS (VALUES
('dmg-ring-protection-1','231-232','ring-of-protection-1','Ring of Protection +1',200000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,'A magic ring granting a continual deflection bonus to Armor Class.','Grants a +1 deflection bonus to AC.','Forge Ring; shield of faith; creator caster level at least three times the ring bonus.'),
('dmg-ring-feather-falling','232','ring-of-feather-falling','Ring of Feather Falling',220000,1,'faint','continuous','Triggers immediately when the wearer falls more than 5 feet.',NULL,NULL,'A feather-patterned ring that arrests a dangerous fall.','Immediately activates as feather fall if the wearer falls more than 5 feet.','Forge Ring; feather fall.'),
('dmg-ring-sustenance','233','ring-of-sustenance','Ring of Sustenance',250000,5,'faint','continuous','Requires one week of continuous wear to attune; removal resets attunement.',NULL,NULL,'A ring that nourishes and refreshes its wearer.','After one full week of continuous wear, provides life-sustaining nourishment and lets 2 hours of sleep provide the benefit of 8 hours. Removing the ring resets the one-week attunement.','Forge Ring; create food and water.'),
('dmg-ring-climbing','230','ring-of-climbing','Ring of Climbing',250000,5,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,'A magic leather finger cord that aids climbing.','Grants +5 competence on Climb checks.','Forge Ring; creator must have 5 ranks in Climb.'),
('dmg-ring-jumping','232','ring-of-jumping','Ring of Jumping',250000,2,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,'A ring that magically enhances leaps.','Grants +5 competence on Jump checks.','Forge Ring; creator must have 5 ranks in Jump.'),
('dmg-ring-swimming','233','ring-of-swimming','Ring of Swimming',250000,2,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,'A silver wave-patterned ring that aids swimming.','Grants +5 competence on Swim checks.','Forge Ring; creator must have 5 ranks in Swim.'),
('dmg-ring-counterspells','230','ring-of-counterspells','Ring of Counterspells',400000,11,'moderate','other','Stores one spell and automatically counters the matching spell when it targets the wearer.',1,'The stored spell is consumed when it counters a matching incoming spell.','A ring that stores one spell solely to counter that same spell.','Stores one spell of 1st through 6th level. A matching spell cast upon the wearer is automatically countered and the ring becomes empty.','Forge Ring; imbue with spell ability.'),
('dmg-ring-mind-shielding','232','ring-of-mind-shielding','Ring of Mind Shielding',800000,3,'faint','continuous','Mental and alignment shielding applies while worn.',NULL,NULL,'A finely made gold ring that wards the wearer''s thoughts and alignment.','The wearer is continuously immune to detect thoughts, discern lies, and magical attempts to discern alignment.','Forge Ring; nondetection.'),
('dmg-ring-protection-2','231-232','ring-of-protection-2','Ring of Protection +2',800000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,'A magic ring granting a continual deflection bonus to Armor Class.','Grants a +2 deflection bonus to AC.','Forge Ring; shield of faith; creator caster level at least 6th.'),
('dmg-ring-force-shield','232','ring-of-force-shield','Ring of Force Shield',850000,9,'moderate','other','Activate or deactivate the force shield as a free action.',NULL,NULL,'An iron ring that creates a weightless shield-shaped wall of force.','The force shield functions as a heavy shield granting +2 shield AC with no armor check penalty or arcane spell failure chance.','Forge Ring; wall of force.'),
('dmg-ring-ram','232','ring-of-the-ram','Ring of the Ram',860000,9,'moderate','command_word','Command the ring and expend 1, 2, or 3 charges.',50,'Charges do not recharge; at 0 charges the ring becomes nonmagical.','An ornate charged ring that projects a ramlike force.','A use spends 1-3 charges, dealing 1d6 damage per charge at up to 50 feet and providing the source-described bull-rush or door-breaking force.','Forge Ring; bull''s strength; telekinesis.'),
('dmg-ring-climbing-improved','230','ring-of-climbing-improved','Ring of Climbing, Improved',1000000,5,'faint','continuous','Competence bonus applies while worn.',NULL,NULL,'A stronger ring of climbing.','Grants +10 competence on Climb checks.','Forge Ring; creator must have 10 ranks in Climb.'),
('dmg-ring-jumping-improved','232','ring-of-jumping-improved','Ring of Jumping, Improved',1000000,7,'moderate','continuous','Competence bonus applies while worn.',NULL,NULL,'A stronger ring of jumping.','Grants +10 competence on Jump checks.','Forge Ring; creator must have 10 ranks in Jump.'),
('dmg-ring-swimming-improved','233','ring-of-swimming-improved','Ring of Swimming, Improved',1000000,7,'moderate','continuous','Competence bonus applies while worn.',NULL,NULL,'A stronger ring of swimming.','Grants +10 competence on Swim checks.','Forge Ring; creator must have 10 ranks in Swim.'),
('dmg-ring-animal-friendship','230','ring-of-animal-friendship','Ring of Animal Friendship',1080000,3,'faint','command_word','Command the ring to use charm animal.',NULL,NULL,'A ring that charms animals on command.','On command, affects one animal as charm animal.','Forge Ring; charm animal.'),
('dmg-ring-energy-resistance-minor','231-232','ring-of-energy-resistance-minor','Ring of Energy Resistance, Minor',1200000,3,'faint','continuous','Energy resistance applies while worn.',NULL,NULL,'A ring attuned to one energy type chosen by its creator.','Continuously grants resistance 10 against one of acid, cold, electricity, fire, or sonic.','Forge Ring; resist energy.'),
('dmg-ring-chameleon-power','230','ring-of-chameleon-power','Ring of Chameleon Power',1270000,3,'faint','other','Free action for chameleon blending; standard action to command disguise self.',NULL,NULL,'A ring that blends its wearer into the surroundings and can disguise them.','Grants +10 competence on Hide checks and can produce disguise self at will.','Forge Ring; disguise self; invisibility.'),
('dmg-ring-water-walking','233','ring-of-water-walking','Ring of Water Walking',1500000,9,'moderate','continuous','Water-walk effect applies while worn.',NULL,NULL,'An opal-set ring that keeps its wearer atop liquid surfaces.','Continuously provides the effects of water walk.','Forge Ring; water walk.'),
('dmg-ring-protection-3','231-232','ring-of-protection-3','Ring of Protection +3',1800000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,'A magic ring granting a continual deflection bonus to Armor Class.','Grants a +3 deflection bonus to AC.','Forge Ring; shield of faith; creator caster level at least 9th.'),
('dmg-ring-spell-storing-minor','232-233','ring-of-spell-storing-minor','Ring of Spell Storing, Minor',1800000,5,'faint','other','Cast a stored spell using its casting time, minimum 1 standard action.',NULL,'Spell-level capacity is 3; expended spells can be replaced.','A ring that stores spells for later use by any wearer.','Stores up to three total spell levels. Stored spells use the minimum caster level needed to cast them unless the source specifies otherwise.','Forge Ring; imbue with spell ability.'),
('dmg-ring-invisibility','232','ring-of-invisibility','Ring of Invisibility',2000000,3,'faint','command_word','Activate to gain invisibility.',NULL,NULL,'A simple silver ring that hides its wearer.','On activation, grants invisibility as the spell.','Forge Ring; invisibility.'),
('dmg-ring-wizardry-1','233','ring-of-wizardry-1','Ring of Wizardry I',2000000,11,'moderate','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,'A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 1st-level arcane spells per day; bonus spells from high ability scores or school specialization are not doubled.','Forge Ring; limited wish.'),
('dmg-ring-evasion','232','ring-of-evasion','Ring of Evasion',2500000,7,'moderate','continuous','Evasion applies while worn.',NULL,NULL,'A ring that grants the defensive benefit of evasion.','Whenever the wearer makes a Reflex save for half damage, a successful save instead results in no damage.','Forge Ring; jump.'),
('dmg-ring-x-ray-vision','233','ring-of-x-ray-vision','Ring of X-Ray Vision',2500000,6,'moderate','command_word','Command to use x-ray vision; extended daily use causes Constitution damage.',NULL,NULL,'A ring that lets its wearer see through solid matter on command.','Vision extends 20 feet through matter within the source limits; after the first 10 minutes of use in one day, each additional minute deals 1 Constitution damage.','Forge Ring; true seeing.'),
('dmg-ring-blinking','230','ring-of-blinking','Ring of Blinking',2700000,7,'moderate','command_word','Command to gain blink.',NULL,NULL,'A ring that shifts its wearer rapidly between the Material and Ethereal Planes.','On command, the wearer gains blink as the spell.','Forge Ring; blink.'),
('dmg-ring-energy-resistance-major','231-232','ring-of-energy-resistance-major','Ring of Energy Resistance, Major',2800000,7,'faint','continuous','Energy resistance applies while worn.',NULL,NULL,'A stronger energy-resistance ring attuned to one energy type.','Continuously grants resistance 20 against one of acid, cold, electricity, fire, or sonic.','Forge Ring; resist energy.'),
('dmg-ring-protection-4','231-232','ring-of-protection-4','Ring of Protection +4',3200000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,'A magic ring granting a continual deflection bonus to Armor Class.','Grants a +4 deflection bonus to AC.','Forge Ring; shield of faith; creator caster level at least 12th.'),
('dmg-ring-wizardry-2','233','ring-of-wizardry-2','Ring of Wizardry II',4000000,14,'strong','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,'A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 2nd-level arcane spells per day; bonus spells from high ability scores or school specialization are not doubled.','Forge Ring; limited wish.'),
('dmg-ring-freedom-movement','232','ring-of-freedom-of-movement','Ring of Freedom of Movement',4000000,7,'moderate','continuous','Freedom-of-movement effect applies while worn.',NULL,NULL,'A gold ring that prevents magical and mundane restraints on movement.','Continuously provides the effects of freedom of movement.','Forge Ring; freedom of movement.'),
('dmg-ring-energy-resistance-greater','231-232','ring-of-energy-resistance-greater','Ring of Energy Resistance, Greater',4400000,11,'moderate','continuous','Energy resistance applies while worn.',NULL,NULL,'The strongest standard energy-resistance ring, attuned to one energy type.','Continuously grants resistance 30 against one of acid, cold, electricity, fire, or sonic.','Forge Ring; resist energy.'),
('dmg-ring-friend-shield-pair','232','ring-of-friend-shield-pair','Rings of Friend Shield (Pair)',5000000,10,'moderate','command_word','Either wearer commands their ring to apply shield other to the wearer of the mate.',NULL,NULL,'A matched pair of rings that let either wearer protect the other at any distance.','The pair functions only together; either wearer can command shield other onto the wearer of the mated ring without a range limitation.','Forge Ring; shield other.'),
('dmg-ring-protection-5','231-232','ring-of-protection-5','Ring of Protection +5',5000000,5,'faint','continuous','Deflection bonus applies while worn.',NULL,NULL,'A magic ring granting a continual deflection bonus to Armor Class.','Grants a +5 deflection bonus to AC.','Forge Ring; shield of faith; creator caster level at least 15th.'),
('dmg-ring-shooting-stars','232-233','ring-of-shooting-stars','Ring of Shooting Stars',5000000,12,'strong','command_word','Command the environment-appropriate power.',NULL,'Powers recharge hourly, nightly, daily, or weekly as listed.','A ring with different powers under open night skies and indoors or underground at night.','Provides the source-listed dancing lights, light, ball lightning, shooting stars, faerie fire, and spark-shower powers with their listed environments and use frequencies.','Forge Ring; light; faerie fire; fireball; lightning bolt.'),
('dmg-ring-spell-storing','232-233','ring-of-spell-storing','Ring of Spell Storing',5000000,9,'moderate','other','Cast a stored spell using its casting time, minimum 1 standard action.',NULL,'Spell-level capacity is 5; expended spells can be replaced.','A ring that stores spells for later use by any wearer.','As the minor ring of spell storing, except it stores up to five total spell levels.','Forge Ring; imbue with spell ability.'),
('dmg-ring-wizardry-3','233','ring-of-wizardry-3','Ring of Wizardry III',7000000,17,'strong','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,'A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 3rd-level arcane spells per day; bonus spells from high ability scores or school specialization are not doubled.','Forge Ring; limited wish.'),
('dmg-ring-telekinesis','233','ring-of-telekinesis','Ring of Telekinesis',7500000,9,'moderate','command_word','Command to use telekinesis.',NULL,NULL,'A ring that produces telekinesis on command.','Allows the wearer to use telekinesis on command.','Forge Ring; telekinesis.'),
('dmg-ring-regeneration','232','ring-of-regeneration','Ring of Regeneration',9000000,15,'strong','continuous','Regenerative benefits apply while worn to damage or losses suffered while the ring is worn.',NULL,NULL,'A white-gold ring that accelerates natural recovery and regrows lost body parts.','For a living wearer, damage taken while wearing the ring heals at 1 hit point per level each hour; nonlethal damage heals at 1 hit point per level every 5 minutes. Lost body parts regenerate as the spell.','Forge Ring; regenerate.'),
('dmg-ring-three-wishes','233','ring-of-three-wishes','Ring of Three Wishes',9795000,20,'strong','other','Activate one remaining ruby to use wish.',3,'Wish charges do not recharge; at 0 charges the ring becomes nonmagical.','A ruby-set ring storing up to three wishes.','Each remaining ruby stores one wish. A randomly generated ring has 1d3 remaining rubies; using the final wish makes the ring nonmagical.','Forge Ring; wish or miracle.'),
('dmg-ring-spell-turning','233','ring-of-spell-turning','Ring of Spell Turning',9828000,13,'strong','command_word','Command up to three times per day.',NULL,'Three activations per day.','A platinum ring that can reflect incoming spells.','Up to three times per day on command, the ring automatically reflects the next nine levels of spells directed at the wearer as spell turning.','Forge Ring; spell turning.'),
('dmg-ring-wizardry-4','233','ring-of-wizardry-4','Ring of Wizardry IV',10000000,20,'strong','continuous','Spell-slot multiplication applies while worn.',NULL,NULL,'A ring for arcane spellcasters that doubles one level of daily spell slots.','Doubles the wearer''s 4th-level arcane spells per day; bonus spells from high ability scores or school specialization are not doubled.','Forge Ring; limited wish.'),
('dmg-ring-djinni-calling','230-231','ring-of-djinni-calling','Ring of Djinni Calling',12500000,17,'strong','other','Rub as a standard action; the bound djinni appears on the next round.',NULL,'Bound djinni service is limited to 1 hour per day.','A legendary ring bound to one specific djinni.','The bound djinni appears when called and faithfully serves for no more than 1 hour per day. If the bound djinni is killed, the ring becomes nonmagical and worthless.','Forge Ring; gate.'),
('dmg-ring-elemental-command-air','230-231','ring-of-elemental-command-air','Ring of Elemental Command (Air)',20000000,15,'strong','other','Common elemental-command protections are continuous; air powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.','A powerful ring attuned to the Elemental Plane of Air.','Common elemental-command powers apply. Air powers include feather fall, resist energy against electricity, gust of wind, wind wall, air walk, and chain lightning with the source-listed frequencies.','Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-elemental-command-earth','230-231','ring-of-elemental-command-earth','Ring of Elemental Command (Earth)',20000000,15,'strong','other','Common elemental-command protections are continuous; earth powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.','A powerful ring attuned to the Elemental Plane of Earth.','Common elemental-command powers apply. Earth powers include meld into stone, soften earth or stone, stone shape, stoneskin, passwall, and wall of stone with the source-listed frequencies.','Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-elemental-command-fire','230-231','ring-of-elemental-command-fire','Ring of Elemental Command (Fire)',20000000,15,'strong','other','Common elemental-command protections are continuous; fire powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.','A powerful ring attuned to the Elemental Plane of Fire.','Common elemental-command powers apply. Fire powers include fire resistance, burning hands, flaming sphere, pyrotechnics, wall of fire, and flame strike with the source-listed frequencies.','Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-elemental-command-water','230-231','ring-of-elemental-command-water','Ring of Elemental Command (Water)',20000000,15,'strong','other','Common elemental-command protections are continuous; water powers use their listed frequencies after awakening.',NULL,'Individual powers recharge on their listed daily or weekly schedules; at-will powers are unlimited.','A powerful ring attuned to the Elemental Plane of Water.','Common elemental-command powers apply. Water powers include water walk, create water, water breathing, wall of ice, ice storm, and control water with the source-listed frequencies.','Forge Ring; summon monster VI; all appropriate spells.'),
('dmg-ring-spell-storing-major','232-233','ring-of-spell-storing-major','Ring of Spell Storing, Major',20000000,17,'strong','other','Cast a stored spell using its casting time, minimum 1 standard action.',NULL,'Spell-level capacity is 10; expended spells can be replaced.','The strongest standard ring of spell storing.','As the minor ring of spell storing, except it stores up to ten total spell levels.','Forge Ring; imbue with spell ability.')
)
INSERT INTO dnd35_items
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,price_copper,weight_pounds,size,hardness,hit_points)
SELECT d.id,'dmg-3.5',d.page,d.slug,d.name,d.description,d.rules_text,0,NULL,1,
       'magic',d.price_copper,NULL,NULL,NULL,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_items i WHERE i.source_id='dmg-3.5' AND i.slug=d.slug AND i.owner_user_id IS NULL
);

