INSERT OR IGNORE INTO dnd35_magic_items
  (item_id,aura_school_id,caster_level,manifester_level,aura_strength,activation,activation_text,slot,
   maximum_charges,recharge_text,enhancement_bonus,craft_cost_copper,craft_xp_cost,crafting_text,crafting_prerequisites)
SELECT d.item_id,NULL,d.caster_level,NULL,d.aura_strength,d.activation,d.activation_text,'other',
       d.maximum_charges,d.recharge_text,NULL,NULL,NULL,d.crafting_text,NULL
FROM desired d;

WITH desired(slug,name,page,kind,summary,tags,mechanics) AS (VALUES
('dmg-ring-energy-type','Ring Energy Type','231-232','rule','Energy-resistance rings are created for one energy type: acid, cold, electricity, fire, or sonic. A treasure-generated ring determines its type randomly.','["magic-items","rings","energy-resistance"]','{"energyTypes":["acid","cold","electricity","fire","sonic"]}'),
('dmg-ring-elemental-command-common','Elemental Command Ring Common Powers','230-231','rule','An awakened elemental-command ring carries the common protections and influence over creatures of its opposed element described by the source, plus the powers of its own element.','["magic-items","rings","elemental-command"]','{"requiresAwakeningPerWearer":true,"variants":["air","earth","fire","water"]}'),
('dmg-ring-spell-storing-generation','Spell-Storing Ring Initial Contents','232-233','procedure','A randomly generated spell-storing ring contains spells selected by the source random-spell procedure up to its spell-level capacity.','["magic-items","rings","spell-storing","random-generation"]','{"capacities":{"minor":3,"standard":5,"major":10}}'),
('dmg-ring-three-wishes-generation','Ring of Three Wishes Remaining Wishes','233','procedure','A randomly generated ring of three wishes has 1d3 remaining wishes.','["magic-items","rings","three-wishes","random-generation"]','{"remainingWishes":"1d3"}'),
